  heading1 = "Check Your Music Rights Now!";
  content1 = "Get instant copyright verification for hassle-free uploads. Try it now for free!";
  action1 = "Check";
  textinputPlaceholder = "Enter YouTube Link (e.g., https://youtube.com/...)";
